import '../../../globals.js';
import { RenderAlpha } from './RenderAlpha.js';
import { RenderBarycentricBlend } from './RenderBarycentricBlend.js';
import { RenderBarycentricPerspectiveBlend } from './RenderBarycentricPerspectiveBlend.js';
import { RenderBlendCompose } from './RenderBlendCompose.js';
import { RenderColor } from './RenderColor.js';
import { RenderDepthSort } from './RenderDepthSort.js';
import { RenderFilter } from './RenderFilter.js';
import { RenderImage } from './RenderImage.js';
import { RenderLinearBlend } from './RenderLinearBlend.js';
import { RenderLinearGradient } from './RenderLinearGradient.js';
import { RenderNormalDebug } from './RenderNormalDebug.js';
import { RenderNormalize } from './RenderNormalize.js';
import { RenderPathBoolean } from './RenderPathBoolean.js';
import { RenderPhong } from './RenderPhong.js';
import { RenderRadialBlend } from './RenderRadialBlend.js';
import { RenderRadialGradient } from './RenderRadialGradient.js';
import { RenderStack } from './RenderStack.js';
import Vector2 from '../../../dot/js/Vector2.js';
import Vector3 from '../../../dot/js/Vector3.js';
import { RenderPremultiply } from './RenderPremultiply.js';
import { RenderUnpremultiply } from './RenderUnpremultiply.js';
import { RenderLinearSRGBToOklab } from './RenderLinearSRGBToOklab.js';
import { RenderOklabToLinearSRGB } from './RenderOklabToLinearSRGB.js';
import { RenderSRGBToLinearSRGB } from './RenderSRGBToLinearSRGB.js';
import { RenderLinearDisplayP3ToLinearSRGB } from './RenderLinearDisplayP3ToLinearSRGB.js';
import { RenderLinearSRGBToLinearDisplayP3 } from './RenderLinearSRGBToLinearDisplayP3.js';
import { RenderLinearSRGBToSRGB } from './RenderLinearSRGBToSRGB.js';
import { RenderPlanar } from './RenderPlanar.js';
import Matrix4 from '../../../dot/js/Matrix4.js';
import Vector4 from '../../../dot/js/Vector4.js';
import { RenderGradientStop } from './RenderGradientStop.js';
import Matrix3 from '../../../dot/js/Matrix3.js';
import { RenderPath } from './RenderPath.js';
import { alpenglow } from '../alpenglow.js';
export const deserializeRenderProgram = (obj) => {
    if (obj.type === 'RenderStack') {
        return deserializeRenderStack(obj);
    }
    else if (obj.type === 'RenderColor') {
        return deserializeRenderColor(obj);
    }
    else if (obj.type === 'RenderAlpha') {
        return deserializeRenderAlpha(obj);
    }
    else if (obj.type === 'RenderDepthSort') {
        return deserializeRenderDepthSort(obj);
    }
    else if (obj.type === 'RenderBlendCompose') {
        return deserializeRenderBlendCompose(obj);
    }
    else if (obj.type === 'RenderPathBoolean') {
        return deserializeRenderPathBoolean(obj);
    }
    else if (obj.type === 'RenderFilter') {
        return deserializeRenderFilter(obj);
    }
    else if (obj.type === 'RenderImage') {
        return deserializeRenderImage(obj);
    }
    else if (obj.type === 'RenderNormalize') {
        return deserializeRenderNormalize(obj);
    }
    else if (obj.type === 'RenderLinearBlend') {
        return deserializeRenderLinearBlend(obj);
    }
    else if (obj.type === 'RenderBarycentricBlend') {
        return deserializeRenderBarycentricBlend(obj);
    }
    else if (obj.type === 'RenderBarycentricPerspectiveBlend') {
        return deserializeRenderBarycentricPerspectiveBlend(obj);
    }
    else if (obj.type === 'RenderLinearGradient') {
        return deserializeRenderLinearGradient(obj);
    }
    else if (obj.type === 'RenderRadialBlend') {
        return deserializeRenderRadialBlend(obj);
    }
    else if (obj.type === 'RenderRadialGradient') {
        return deserializeRenderRadialGradient(obj);
    }
    else if (obj.type === 'RenderColorSpaceConversion') {
        return deserializeRenderColorSpaceConversion(obj);
    }
    else if (obj.type === 'RenderPhong') {
        return deserializeRenderPhong(obj);
    }
    else if (obj.type === 'RenderNormalDebug') {
        return deserializeRenderNormalDebug(obj);
    }
    throw new Error(`Unrecognized RenderProgram type: ${obj.type}`);
};
alpenglow.register('deserializeRenderProgram', deserializeRenderProgram);
export const deserializeRenderAlpha = (obj) => {
    return new RenderAlpha(deserializeRenderProgram(obj.program), obj.alpha);
};
export const deserializeRenderBarycentricBlend = (obj) => {
    return new RenderBarycentricBlend(new Vector2(obj.pointA[0], obj.pointA[1]), new Vector2(obj.pointB[0], obj.pointB[1]), new Vector2(obj.pointC[0], obj.pointC[1]), obj.accuracy, deserializeRenderProgram(obj.a), deserializeRenderProgram(obj.b), deserializeRenderProgram(obj.c));
};
export const deserializeRenderBarycentricPerspectiveBlend = (obj) => {
    return new RenderBarycentricPerspectiveBlend(new Vector3(obj.pointA[0], obj.pointA[1], obj.pointA[2]), new Vector3(obj.pointB[0], obj.pointB[1], obj.pointB[2]), new Vector3(obj.pointC[0], obj.pointC[1], obj.pointC[2]), obj.accuracy, deserializeRenderProgram(obj.a), deserializeRenderProgram(obj.b), deserializeRenderProgram(obj.c));
};
export const deserializeRenderBlendCompose = (obj) => {
    return new RenderBlendCompose(obj.composeType, obj.blendType, deserializeRenderProgram(obj.a), deserializeRenderProgram(obj.b));
};
export const deserializeRenderColorSpaceConversion = (obj) => {
    const program = deserializeRenderProgram(obj.program);
    if (obj.subtype === 'RenderPremultiply') {
        return new RenderPremultiply(program);
    }
    else if (obj.subtype === 'RenderUnpremultiply') {
        return new RenderUnpremultiply(program);
    }
    else if (obj.subtype === 'RenderLinearSRGBToOklab') {
        return new RenderLinearSRGBToOklab(program);
    }
    else if (obj.subtype === 'RenderLinearSRGBToSRGB') {
        return new RenderLinearSRGBToSRGB(program);
    }
    else if (obj.subtype === 'RenderOklabToLinearSRGB') {
        return new RenderOklabToLinearSRGB(program);
    }
    else if (obj.subtype === 'RenderSRGBToLinearSRGB') {
        return new RenderSRGBToLinearSRGB(program);
    }
    else if (obj.subtype === 'RenderLinearDisplayP3ToLinearSRGB') {
        return new RenderLinearDisplayP3ToLinearSRGB(program);
    }
    else if (obj.subtype === 'RenderLinearSRGBToLinearDisplayP3') {
        return new RenderLinearSRGBToLinearDisplayP3(program);
    }
    else {
        throw new Error(`Unrecognized subtype: ${obj.subtype}`);
    }
};
export const deserializeRenderDepthSort = (obj) => {
    return new RenderDepthSort(obj.items.map(item => new RenderPlanar(deserializeRenderProgram(item.program), new Vector3(item.pointA[0], item.pointA[1], item.pointA[2]), new Vector3(item.pointB[0], item.pointB[1], item.pointB[2]), new Vector3(item.pointC[0], item.pointC[1], item.pointC[2]))));
};
export const deserializeRenderFilter = (obj) => {
    return new RenderFilter(deserializeRenderProgram(obj.program), new Matrix4(...obj.colorMatrix), new Vector4(obj.colorTranslation[0], obj.colorTranslation[1], obj.colorTranslation[2], obj.colorTranslation[3]));
};
export const deserializeRenderGradientStop = (obj) => {
    return new RenderGradientStop(obj.ratio, deserializeRenderProgram(obj.program));
};
export const deserializeRenderRadialGradient = (obj) => {
    return new RenderRadialGradient(Matrix3.rowMajor(obj.transform[0], obj.transform[1], obj.transform[2], obj.transform[3], obj.transform[4], obj.transform[5], obj.transform[6], obj.transform[7], obj.transform[8]), new Vector2(obj.start[0], obj.start[1]), obj.startRadius, new Vector2(obj.end[0], obj.end[1]), obj.endRadius, obj.stops.map(stop => deserializeRenderGradientStop(stop)), obj.extend, obj.accuracy);
};
export const deserializeRenderLinearGradient = (obj) => {
    return new RenderLinearGradient(Matrix3.rowMajor(obj.transform[0], obj.transform[1], obj.transform[2], obj.transform[3], obj.transform[4], obj.transform[5], obj.transform[6], obj.transform[7], obj.transform[8]), new Vector2(obj.start[0], obj.start[1]), new Vector2(obj.end[0], obj.end[1]), obj.stops.map(stop => deserializeRenderGradientStop(stop)), obj.extend, obj.accuracy);
};
export const deserializeRenderStack = (obj) => {
    return new RenderStack(obj.children.map(child => deserializeRenderProgram(child)));
};
export const deserializeRenderColor = (obj) => {
    return new RenderColor(new Vector4(obj.color.r, obj.color.g, obj.color.b, obj.color.a));
};
export const deserializeRenderPathBoolean = (obj) => {
    return new RenderPathBoolean(RenderPath.deserialize(obj.path), deserializeRenderProgram(obj.inside), deserializeRenderProgram(obj.outside));
};
export const deserializeRenderImage = (obj) => {
    return new RenderImage(Matrix3.rowMajor(obj.transform[0], obj.transform[1], obj.transform[2], obj.transform[3], obj.transform[4], obj.transform[5], obj.transform[6], obj.transform[7], obj.transform[8]), RenderImage.deserializeRenderImageable(obj.image), obj.extendX, obj.extendY, obj.resampleType);
};
export const deserializeRenderNormalize = (obj) => {
    return new RenderNormalize(deserializeRenderProgram(obj.program));
};
export const deserializeRenderLinearBlend = (obj) => {
    return new RenderLinearBlend(new Vector2(obj.scaledNormal[0], obj.scaledNormal[1]), obj.offset, obj.accuracy, deserializeRenderProgram(obj.zero), deserializeRenderProgram(obj.one));
};
export const deserializeRenderRadialBlend = (obj) => {
    return new RenderRadialBlend(Matrix3.rowMajor(obj.transform[0], obj.transform[1], obj.transform[2], obj.transform[3], obj.transform[4], obj.transform[5], obj.transform[6], obj.transform[7], obj.transform[8]), obj.radius0, obj.radius1, obj.accuracy, deserializeRenderProgram(obj.zero), deserializeRenderProgram(obj.one));
};
export const deserializeRenderPhong = (obj) => {
    // @ts-expect-error
    return new RenderPhong(obj.alpha, ...obj.children.map(deserializeRenderProgram));
};
export const deserializeRenderNormalDebug = (obj) => {
    return new RenderNormalDebug(deserializeRenderProgram(obj.normalProgram));
};
